import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_W 32
#define TILE_H 8
#define ROWS_PER_THREAD 16
#define OUT_TILE_H (TILE_H * ROWS_PER_THREAD)
__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int channels, int height, int width,
    int kernel_size, int stride, int padding, int dilation,
    int height_out, int width_out)
{
    extern __shared__ float smem[];
    int bc = blockIdx.z; // combined batch*channel index
    int c = bc % channels;
    int b = bc / channels;
    int wo_start = blockIdx.x * TILE_W;
    int ho_start = blockIdx.y * OUT_TILE_H;
    int wo = wo_start + threadIdx.x;
    int h_in_start = ho_start * stride - padding;
    int h_in_last = (ho_start + OUT_TILE_H - 1) * stride - padding + (kernel_size - 1) * dilation;
    int needed_height = h_in_last - h_in_start + 1;
    int w_in = wo * stride - padding;
    const float* in_base = input + ((b * channels + c) * height) * width;
    // Cooperative load of the reusable input tile into shared memory.
    // Each thread column owns a single input column (kernel width = 1),
    // and threads along y cooperatively load all rows needed for this tile.
    for (int r = threadIdx.y; r < needed_height; r += TILE_H) {
        int h_in = h_in_start + r;
        float val = 0.0f;
        if (h_in >= 0 && h_in < height && wo < width_out && w_in >= 0 && w_in < width) {
            val = in_base[h_in * width + w_in];
        }
        smem[r * TILE_W + threadIdx.x] = val;
    }
    __syncthreads();
    const float* w_ptr = weight + c * kernel_size;
    #pragma unroll
    for (int i = 0; i < ROWS_PER_THREAD; ++i) {
        int ho = ho_start + i * TILE_H + threadIdx.y;
        if (ho < height_out && wo < width_out) {
            float sum = 0.0f;
            #pragma unroll
            for (int kh = 0; kh < kernel_size; ++kh) {
                int h_in = ho * stride - padding + kh * dilation;
                int rel = h_in - h_in_start;
                sum += smem[rel * TILE_W + threadIdx.x] * w_ptr[kh];
            }
            if (bias != nullptr) {
                sum += bias[c];
            }
            output[((b * channels + c) * height_out + ho) * width_out + wo] = sum;
        }
    }
}
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);
    int kernel_size = weight.size(2); // weight shape: (channels, 1, kernel_size, 1)
    int height_out = (height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int width_out = (width + 2 * padding - dilation * (1 - 1) - 1) / stride + 1;
    auto output = torch::zeros({batch_size, channels, height_out, width_out}, input.options());
    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (width_out + TILE_W - 1) / TILE_W,
        (height_out + OUT_TILE_H - 1) / OUT_TILE_H,
        batch_size * channels
    );
    int needed_height = (OUT_TILE_H - 1) * stride + (kernel_size - 1) * dilation + 1;
    size_t shared_mem_bytes = (size_t)needed_height * TILE_W * sizeof(float);
    depthwise_conv2d_kernel<<<grid, block, shared_mem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, channels, height, width,
        kernel_size, stride, padding, dilation,
        height_out, width_out
    );
    return output;
}
"""

cpp_source = r"""
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation);
"""

depthwise_conv2d_module = load_inline(
    name="depthwise_conv2d_module",
    cpp_sources=cpp_source,
    cuda_sources=source,
    functions=["depthwise_conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric kernel,
    using a custom CUDA kernel for the forward pass.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        # Weight shape matches nn.Conv2d depthwise weight: (in_channels, 1, kernel_size, 1)
        self.weight = nn.Parameter(torch.empty(in_channels, 1, kernel_size, 1))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(in_channels))
            fan_in = kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

        self.conv_fn = depthwise_conv2d_module.depthwise_conv2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias_tensor = self.bias if self.bias is not None else torch.tensor([], device=x.device, dtype=x.dtype)
        return self.conv_fn(
            x, self.weight, bias_tensor,
            self.stride, self.padding, self.dilation
        )


